"""Compare top-level defs between a source file at main and its relocation targets at PR head.

Reports: identical / MODIFIED / MISSING, and duplicates across targets.
"""
import ast
import sys
from pathlib import Path


def top_level_defs(path: Path) -> dict[str, str]:
    """name -> exact source text including decorators."""
    src = path.read_text(encoding="utf-8")
    lines = src.splitlines(keepends=True)
    tree = ast.parse(src, filename=str(path))
    out: dict[str, str] = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            start = node.lineno
            if node.decorator_list:
                start = min(start, min(d.lineno for d in node.decorator_list))
            # back up over the decorator '@' line start
            seg = "".join(lines[start - 1 : node.end_lineno])
            if node.name in out:
                out[node.name + f"#dup@{node.lineno}"] = seg
            else:
                out[node.name] = seg
    return out


def module_assignments(path: Path) -> dict[str, str]:
    src = path.read_text(encoding="utf-8")
    lines = src.splitlines(keepends=True)
    tree = ast.parse(src, filename=str(path))
    out: dict[str, str] = {}
    for node in tree.body:
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for t in targets:
                if isinstance(t, ast.Name):
                    out[t.id] = "".join(lines[node.lineno - 1 : node.end_lineno])
    return out


source_file = Path(sys.argv[1])
targets = [Path(p) for p in sys.argv[2:]]

src_defs = top_level_defs(source_file)
src_assigns = module_assignments(source_file)

tgt_defs: dict[str, list[tuple[str, str]]] = {}
tgt_assigns: dict[str, list[tuple[str, str]]] = {}
for t in targets:
    for name, seg in top_level_defs(t).items():
        tgt_defs.setdefault(name, []).append((t.name, seg))
    for name, seg in module_assignments(t).items():
        tgt_assigns.setdefault(name, []).append((t.name, seg))

identical, modified, missing, dup = [], [], [], []
for name, seg in src_defs.items():
    hits = tgt_defs.get(name, [])
    if not hits:
        missing.append(name)
        continue
    if len(hits) > 1:
        dup.append((name, [h[0] for h in hits]))
    if any(h[1] == seg for h in hits):
        identical.append(name)
    else:
        modified.append((name, [h[0] for h in hits]))

print(f"SOURCE: {source_file.name}   ({len(src_defs)} top-level defs, {len(src_assigns)} module assigns)")
print(f"TARGETS: {', '.join(t.name for t in targets)}")
print()
print(f"  identical defs : {len(identical)}")
print(f"  MODIFIED defs  : {len(modified)}")
print(f"  MISSING defs   : {len(missing)}")
print(f"  duplicated defs: {len(dup)}")
print()
if modified:
    print("--- MODIFIED (body differs from main) ---")
    for name, where in modified:
        print(f"  {name}   -> found in {where}")
if missing:
    print("--- MISSING (no top-level def with this name anywhere in targets) ---")
    for name in missing:
        print(f"  {name}")
if dup:
    print("--- DUPLICATED across targets ---")
    for name, where in dup:
        print(f"  {name} -> {where}")

# module-level assignments
a_ident, a_mod, a_missing = [], [], []
for name, seg in src_assigns.items():
    hits = tgt_assigns.get(name, [])
    if not hits:
        a_missing.append(name)
    elif any(h[1] == seg for h in hits):
        a_ident.append(name)
    else:
        a_mod.append((name, [h[0] for h in hits]))
print()
print(f"  module assigns identical: {len(a_ident)}  MODIFIED: {len(a_mod)}  MISSING: {len(a_missing)}")
if a_mod:
    print("--- MODIFIED module assignments ---")
    for name, where in a_mod:
        print(f"  {name} -> {where}")
if a_missing:
    print("--- MISSING module assignments ---")
    for name in a_missing:
        print(f"  {name}")

#!/usr/bin/env python3
"""Detect decorators separated from their def/class by blank lines or comments.

Normal style puts the decorator immediately above the def. A gap is the
signature of a decorator orphaned by a code move (the moved def was deleted,
the decorator stayed and re-attached to whatever def followed).
"""
import ast
import sys
from pathlib import Path

root = Path(sys.argv[1])
hits = 0
for path in sorted((root / "scripts").rglob("*.py")):
    try:
        src = path.read_text(encoding="utf-8")
        tree = ast.parse(src, filename=str(path))
    except (SyntaxError, UnicodeDecodeError):
        continue
    lines = src.splitlines()
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        for dec in node.decorator_list:
            end = getattr(dec, "end_lineno", dec.lineno)
            # lines strictly between decorator end and the next decorator/def line
            nxt = min(
                [d.lineno for d in node.decorator_list if d.lineno > end] + [node.lineno]
            )
            gap = [lines[i - 1] for i in range(end + 1, nxt)]
            if gap:
                hits += 1
                rel = path.relative_to(root)
                print(f"{rel}:{end}: decorator '@{ast.unparse(dec)}' separated from "
                      f"'{node.name}' (line {node.lineno}) by {len(gap)} line(s)")
                for g in gap:
                    print(f"      gap> {g!r}")
print(f"\nTOTAL orphan-gap decorators: {hits}")

