#!/usr/bin/env python3
"""Which assert_*/test_* functions are actually reachable from each test module's main()?

Builds an intra-module call graph over Name loads and walks from main().
Cross-module: a name imported from another module is followed into that module.
"""
import ast
import sys
from pathlib import Path


class Module:
    def __init__(self, path: Path):
        self.path = path
        self.name = path.stem
        src = path.read_text(encoding="utf-8")
        self.tree = ast.parse(src, filename=str(path))
        self.defs: dict[str, ast.AST] = {}
        for n in ast.walk(self.tree):
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
                self.defs.setdefault(n.name, n)
        # name -> source module for `from X import a, b`
        self.imported_from: dict[str, str] = {}
        for n in self.tree.body:
            if isinstance(n, ast.ImportFrom) and n.module:
                for a in n.names:
                    self.imported_from[a.asname or a.name] = n.module

    def refs(self, node: ast.AST) -> set[str]:
        out = set()
        for x in ast.walk(node):
            if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load):
                out.add(x.id)
        return out


def load_all(paths: list[Path]) -> dict[str, Module]:
    return {p.stem: Module(p) for p in paths}


def reachable(mods: dict[str, Module], start_mod: str, start_fn: str = "main") -> set[tuple[str, str]]:
    seen: set[tuple[str, str]] = set()
    stack = [(start_mod, start_fn)]
    while stack:
        mname, fname = stack.pop()
        if (mname, fname) in seen:
            continue
        m = mods.get(mname)
        if m is None or fname not in m.defs:
            continue
        seen.add((mname, fname))
        for r in m.refs(m.defs[fname]):
            if r in m.defs:
                stack.append((mname, r))
            elif r in m.imported_from and m.imported_from[r] in mods:
                stack.append((m.imported_from[r], r))
    return seen


def is_check(name: str) -> bool:
    return name.startswith("assert_") or name.startswith("test_")


tree_root = Path(sys.argv[1])
runners = sys.argv[2].split(",")
extra = sys.argv[3].split(",") if len(sys.argv) > 3 and sys.argv[3] else []

paths = [tree_root / "scripts" / f"{n}.py" for n in runners + extra]
mods = load_all([p for p in paths if p.exists()])

executed: set[str] = set()
for r in runners:
    if r not in mods:
        print(f"  !! runner module missing: {r}")
        continue
    got = reachable(mods, r)
    checks = {fn for _, fn in got if is_check(fn)}
    print(f"  {r}.main() -> {len(checks)} checks reachable")
    executed |= checks

# every check DEFINED anywhere in these modules
defined: dict[str, list[str]] = {}
for mname, m in mods.items():
    for fn in m.defs:
        if is_check(fn):
            defined.setdefault(fn, []).append(mname)

print(f"\n  total checks DEFINED   : {len(defined)}")
print(f"  total checks EXECUTED  : {len(executed)}")
orphaned = sorted(set(defined) - executed)
print(f"  DEFINED BUT NEVER RUN  : {len(orphaned)}")
for o in orphaned:
    print(f"      {o}   (defined in {defined[o]})")

Path(sys.argv[0] + f".{tree_root.name}.executed").write_text("\n".join(sorted(executed)))

